	/**
	 * Default Constructor
	 */
    public ActivityService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ActivityEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ActivityRepository.class) );
		this.validator		= applicationContext.getBean(ActivityValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Activity
	 */
		public Activity createActivity( CreateActivityCommand command ) {

		Activity entity = new Activity();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setActivityId( command.getActivityId() );
            entity.setSubject( command.getSubject() );
            entity.setDueDate( command.getDueDate() );
            entity.setStartAt( command.getStartAt() );
            entity.setEndAt( command.getEndAt() );
            entity.setLocation( command.getLocation() );
            entity.setActivityType( command.getActivityType() );
            entity.setStatus( command.getStatus() );
            entity.setPriority( command.getPriority() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Activity {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateActivityCommand
	 * @return		Activity
	 */
	public Activity updateActivity( UpdateActivityCommand command ) {

		Activity entity = new Activity();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setActivityId( command.getActivityId() );
            entity.setSubject( command.getSubject() );
            entity.setDueDate( command.getDueDate() );
            entity.setStartAt( command.getStartAt() );
            entity.setEndAt( command.getEndAt() );
            entity.setLocation( command.getLocation() );
            entity.setOrganization( command.getOrganization() );
            entity.setOwner( command.getOwner() );
            entity.setAccount( command.getAccount() );
            entity.setContact( command.getContact() );
            entity.setLead( command.getLead() );
            entity.setOpportunity( command.getOpportunity() );
            entity.setCase( command.getCase() );
            entity.setCampaign( command.getCampaign() );
            entity.setActivityType( command.getActivityType() );
            entity.setStatus( command.getStatus() );
            entity.setPriority( command.getPriority() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Activity {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteActivityCommand
	 */
	public void delete( DeleteActivityCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getActivityId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Activity {0} ", id );

	}

	/**
	 * Method to retrieve the Activity via ActivityFetchOneSummary
	 * @param 	summary ActivityFetchOneSummary
	 * @return 	ActivityFetchOneResponse
	 */
	public Activity getActivity( ActivityFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ActivityFetchOneSummary arg cannot be null" );

		Activity entity = null;
		UUID id = summary.getActivityId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Activity using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Activitys
	 *
	 * @return 	List<Activity>
	 */
    public List<Activity> getAllActivity() {
		List<Activity> list = projector.findAll( new FindAllActivityQuery() );
		return list;
	}

	/**
	 * assign Organization on Activity
	 * @param		command AssignOrganizationToActivityCommand
	 */
	public void assignOrganization( AssignOrganizationToActivityCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrganization(command.getActivityId(), command.getAssignment());

	}

